#include "SoundEssentials.h"

#include "AudioProvenance.h"
#include "Out.h"

// generated by tools/sound-library/embed_essentials.py
#include "sound_essentials.h"

#include <map>
#include <set>

using namespace jasperengine;
using namespace jasperengine::editor;

namespace {

struct Essentials {
    std::vector<SoundManifestClip> clips;
    std::map<std::string, const SoundEssentialsFile*> files;
};

const Essentials& essentials() {
    static const Essentials data = []() {
        Essentials c;
        const std::string text(reinterpret_cast<const char*>(sound_essentials_manifest), sound_essentials_manifest_size);
        SoundManifest parsed;
        std::string error;
        if (!SoundManifest::parse(text, SoundManifest::ESSENTIALS_FORMAT, parsed, error)) {
            Out::error("Sound essentials: the embedded manifest is invalid (" + error + "); the essentials are not available");
            return c;
        }
        for (unsigned int i = 0; i < sound_essentials_file_count; i++) c.files[sound_essentials_files[i].path] = &sound_essentials_files[i];
        for (const SoundManifestClip& clip : parsed.clips) {
            if (c.files.count(clip.path)) c.clips.push_back(clip);
        }
        return c;
    }();
    return data;
}

} // namespace

const std::vector<SoundManifestClip>& SoundEssentials::all() {
    return essentials().clips;
}

const SoundManifestClip* SoundEssentials::find(const std::string& id) {
    for (const SoundManifestClip& clip : all()) {
        if (clip.id == id) return &clip;
    }
    return nullptr;
}

std::string SoundEssentials::bytes(const SoundManifestClip& clip) {
    const auto it = essentials().files.find(clip.path);
    return it == essentials().files.end() ? std::string() : std::string(reinterpret_cast<const char*>(it->second->data), it->second->size);
}

std::vector<std::string> SoundEssentials::groups() {
    std::set<std::string> unique;
    for (const SoundManifestClip& clip : all()) unique.insert(clip.group);
    return std::vector<std::string>(unique.begin(), unique.end());
}

bool SoundEssentials::isReference(const std::string& text) {
    return text.rfind(PREFIX, 0) == 0;
}

bool SoundEssentials::match(const std::string& reference, std::vector<const SoundManifestClip*>& out, std::string& error) {
    if (!isReference(reference)) {
        error = reference + " is not an essentials: reference";
        return false;
    }
    const std::string pattern = reference.substr(std::string(PREFIX).size());
    const size_t before = out.size();
    if (pattern == "*") {
        for (const SoundManifestClip& clip : all()) out.push_back(&clip);
    } else if (pattern.size() > 2 && pattern.compare(pattern.size() - 2, 2, "/*") == 0) {
        const std::string group = pattern.substr(0, pattern.size() - 2);
        for (const SoundManifestClip& clip : all()) {
            if (clip.group == group) out.push_back(&clip);
        }
    } else if (const SoundManifestClip* clip = find(pattern)) {
        out.push_back(clip);
    }
    if (out.size() == before) {
        std::string list;
        for (const std::string& group : groups()) list += (list.empty() ? "" : ", ") + group;
        error = "unknown essential \"" + pattern + "\": use essentials:<group>/<name>, essentials:<group>/* or essentials:*; groups: " + list +
                " (search_sounds scope essentials lists the ids)";
        return false;
    }
    return true;
}

AudioAnalysis::Labels SoundEssentials::labels(const SoundManifestClip& clip) {
    AudioAnalysis::Labels labels;
    labels.type = clip.type;
    labels.manifestKind = clip.kind;
    labels.tags = clip.tags;
    AudioProvenance provenance;
    provenance.values = clip.meta.value("provenance", nlohmann::json::object());
    provenance.values.erase("version");
    labels.licence = provenance.licenceJson();
    return labels;
}
